290	async function provision(job: Job) {
291	  const server = await loadServer(job);
292	  // Clear any stale failure reason from a previous attempt as this run starts, so
293	  // a successful retry doesn't leave the last error hanging around on the row.
294	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null } });
295	
296	  if (SANDBOX) {
297	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
298	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
299	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
300	    const password = generatePassword();
301	    const ip = sandboxIp(vmid);
302	    await db.server.update({
303	      where: { id: server.id },
304	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
305	    });
306	    await notify(
307	      server.userId,
308	      `Server ${server.hostname} is ready`,
309	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
310	      `/dashboard/servers/${server.id}`
311	    );
312	    // Post-purchase review request (once per server, skipped if no profiles set).
313	    await sendReviewRequestForServer(server.id);
314	    return;
315	  }
316	
317	  const { conn, row: nodeRow } = await nodeFor(server);
318	  const storage = server.plan.storageTier === "hdd"
319	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
320	    : nodeRow?.storageNvme ?? "vmdata";
321	
322	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
323	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
324	  // server's vzdump archives, so the id freed by a deletion comes back carrying
325	  // the old owner's backups — which every backup surface then attributes to the
326	  // new customer (listBackups/requestRestore key on vmid alone). See
327	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
328	  // keeps the vmid already persisted on the row.
329	  const vmid = server.vmid ?? (await allocateFreshVmid(conn));
330	  const password = generatePassword();
331	
332	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
333	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
334	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
335	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
336	  const { getSettingBool: _settingBool } = await import("../lib/settings");
337	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
338	  if (wantDedicated && ovhConfigured()) {
339	    try {
340	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
341	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
342	      dedicated = await allocateDedicatedIp(server.id, vmid);
343	    } catch (e) {
344	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
345	    }
346	  }
347	  // Node-aware + transactionally-claimed allocation (passing the server id enables
348	  // the claim path, so two concurrent provisions can't pick the same IP/port).
349	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
350	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
351	
352	  await db.server.update({
353	    where: { id: server.id },
354	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
355	  });
356	
357	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
358	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
359	  // (worker restart mid-clone, or any transient failure in the steps below) would
360	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
361	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
362	  // the clone is idempotent, so skip it when the VM is already present.
363	  let vmAlreadyExists = false;
364	  try {
365	    await conn.vmStatus(vmid);
366	    vmAlreadyExists = true;
367	  } catch {
368	    vmAlreadyExists = false;
369	  }
370	  if (vmAlreadyExists) {
371	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
372	  } else {
373	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
374	      newid: vmid,
375	      name: server.hostname,
376	      full: 1,
377	      storage,
378	    });
379	    await conn.waitForTask(cloneUpid, 600_000);
380	  }
381	
382	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
383	  //
384	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
385	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
386	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
387	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
388	  // all silently vanish, and the customer is still told the server is ready.
389	  // Failing here is recoverable — the job retries, and the clone above is
390	  // idempotent. Continuing is not.
391	  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
392	  // generate its one-time admin password (persisted, once) and get the idempotent
393	  // install script to bake into cloud-init. Null for an ordinary VPS.
394	  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
395	
396	  const snippet = buildCloudInit(server);
397	  try {
398	    await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8");
399	  } catch (e: any) {
400	    throw new Error(
401	      `could not write the cloud-init snippet ${SNIPPET_DIR}/nxeon-${vmid}.yaml (${e?.message ?? e}). ` +
402	        `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
403	        `stopped here rather than reporting a server that would not be usable.`
404	    );
405	  }
406	
407	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
408	  const sshkeys = keys.length
409	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
410	    : undefined;
411	  const cfg: Record<string, any> = {
412	    cores: server.plan.cpuCores,
413	    memory: server.plan.ramMB,
414	    ciuser: "root",
415	    cipassword: password,
416	    sshkeys,
417	    nameserver: "1.1.1.1 8.8.8.8",
418	    onboot: 1,
419	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
420	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
421	  };
422	  if (dedicated) {
423	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
424	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
425	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
426	  } else {
427	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
428	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
429	  }
430	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
431	
432	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
433	  // customer bought as a deploy-time upsell, so the VM is born the right size and
434	  // no separate DISK_EXPAND job is needed on a fresh order.
435	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
436	    disk: "scsi0",
437	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
438	  });
439	
440	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
441	  // for a NAT server. If it cannot be proved, the readiness message says so
442	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
443	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
444	  // its IP, which is a worse outcome than a missing forward.
445	  let natError: Error | null = null;
446	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
447	
448	  // Idempotent start. A worker restart (e.g. a deploy) can interrupt a provision
449	  // AFTER the VM was already created and started; the reaper then re-queues the job.
450	  // Starting an already-running VM makes Proxmox's start task fail with "already
451	  // running", which — before this guard — stranded a perfectly good, reachable VM in
452	  // ERROR forever (every retry hit the same wall). So skip the start when the VM is
453	  // already running, and treat an "already running" race as success rather than fatal.
454	  const alreadyRunning = await conn
455	    .vmStatus(vmid)
456	    .then((s: { status?: string } | null) => s?.status === "running")
457	    .catch(() => false);
458	  if (!alreadyRunning) {
459	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
460	    try {
461	      await conn.waitForTask(startUpid);
462	    } catch (e) {
463	      if (!/already running/i.test(String((e as { message?: unknown })?.message ?? ""))) throw e;
464	    }
465	  }
466	
467	  // `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
468	  // agent whether the machine actually booted before calling it ready (M7 #10).
469	  // A false here is reported, never downgraded into silence.
470	  const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);
471	
472	  const runningServer = await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
473	
474	  // Deployment confirmation email (transactional, deduped via EmailLog). Runs on
475	  // the provision money-path, so it is best-effort and must never fail the build.
476	  try {
477	    const { sendServerDeployedEmail } = await import("../lib/server-deployed-email");
478	    await sendServerDeployedEmail(server, (server as any).user);
479	  } catch (e) {
480	    console.error("[worker] deployment-confirmation email failed (non-fatal)", e);
481	  }
482	  // Tell the partner (best-effort, never blocks provisioning) — only for orders
483	  // tagged via a partner deep link (see PartnerSourceCapture + payAndDeploy).
484	  // Most VPS orders are direct Nxeon customers and must never be forwarded to a
485	  // partner's webhook.
486	  if (runningServer.partnerSource === "kodely") {
487	    try {
488	      const { notifyPartner } = await import("../lib/partner");
489	      await notifyPartner("vps.provisioned", {
490	        userId: runningServer.userId,
491	        serverId: runningServer.id,
492	        hostname: runningServer.hostname,
493	        ipAddress: runningServer.ipAddress,
494	      });
495	    } catch (e) {
496	      console.error("[worker] partner notify failed (non-fatal)", e);
497	    }
498	  }
499	
500	  const isImage = server.osTemplate.category !== "PLAIN_OS";
501	  const sshLine = dedicated
502	    ? `ssh root@${dedicated.address}`
503	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
504	
505	  const caveats: string[] = [];
506	  if (natError) {
507	    caveats.push(
508	      `Port forwarding could NOT be confirmed for this server, so the SSH command above may not connect yet — ` +
509	        `we are not going to pretend otherwise. Support has been alerted (${natError.message.slice(0, 200)}).`
510	    );
511	  }
512	  if (!booted) {
513	    caveats.push(
514	      "The hypervisor started the VM, but its guest agent has not answered yet, so we cannot confirm the " +
515	        "operating system finished booting. Give it a few more minutes; if the SSH command still fails, open a ticket."
516	    );
517	  }
518	  const body = [
519	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
520	    ...caveats,
521	  ].join(" — ");
522	  await notify(
523	    server.userId,
524	    // Never assert "ready" for something we could not verify.
525	    caveats.length ? `Server ${server.hostname} is up, with caveats` : `Server ${server.hostname} is ready`,
526	    body,
527	    `/dashboard/servers/${server.id}`
528	  );
529	  // Post-purchase review request (once per server, skipped if no profiles set).
530	  await sendReviewRequestForServer(server.id);
531	}
