789	/**
790	 * Tell the customer their server failed to provision. Before this, a terminal
791	 * PROVISION failure flipped the server to ERROR and sent NOTHING — the customer
792	 * paid, then sat on a dead screen with a red dot and no explanation. Persists a
793	 * short human reason on `Server.provisionError` (surfaced in the ERROR banner on
794	 * the detail page), drops an in-app notification, and emails them. Best-effort on
795	 * every leg — a failed notification must never mask the underlying job failure.
796	 *
797	 * `error` is the redacted Job.error; we keep a trimmed copy for the customer.
798	 */
799	async function notifyProvisionFailed(
800	  server: { id: string; userId: string; hostname: string },
801	  error: string,
802	): Promise<void> {
803	  // A concise, customer-facing reason. The raw Job.error can be a 2000-char stack;
804	  // the first line is almost always the meaningful message.
805	  const reason = (error.split("\n")[0] || error).trim().slice(0, 300);
806	  try {
807	    await db.server.update({ where: { id: server.id }, data: { provisionError: reason } });
808	  } catch (e) {
809	    console.error("[worker] persist provisionError failed", e);
810	  }
811	  // If this VM backs a managed NxCloud, mark the wrapper FAILED too — otherwise a
812	  // failed nxcloud provision leaves the instance stuck on "setting up" forever
813	  // while the backing Server sits in ERROR. Its dashboard card reads this to show
814	  // the failed/retry state (components/customer/NxcloudClient.tsx).
815	  try {
816	    await db.nxCloudInstance.updateMany({
817	      where: { serverId: server.id, status: { notIn: ["DELETING", "ACTIVE"] } },
818	      data: { status: "FAILED", error: reason },
819	    });
820	  } catch (e) {
821	    console.error("[worker] mark nxcloud instance failed", e);
822	  }
823	  await notify(
824	    server.userId,
825	    `We couldn't set up ${server.hostname}`,
826	    `Provisioning failed and our team has been notified. You can retry it or contact support from the server page.`,
827	    `/dashboard/servers/${server.id}`,
828	  );
829	  try {
830	    const { sendMail, emails } = await import("../lib/mailer");
831	    const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
832	    if (user?.email) {
833	      const tpl = emails.provisionFailed({ hostname: server.hostname, reason });
834	      await sendMail({
835	        to: user.email,
836	        subject: tpl.subject,
837	        html: tpl.html,
838	        template: tpl.template,
839	        userId: server.userId,
840	        // No `kind` → always send. A paid-for server that failed to build is a
841	        // service-delivery failure the customer must hear about.
842	      });
843	    }
844	  } catch (e) {
845	    console.error("[worker] provision-failure email failed", e);
846	  }
847	}
