1295	async function runJob(job: Job) {
1296	  // The job is already atomically claimed (status RUNNING, attempts incremented)
1297	  // by the loop's compare-and-swap before we get here — see the CAS in main().
1298	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
1299	  try {
1300	    await handlers[job.type](job);
1301	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
1302	    console.log(`[worker] job ${job.id} DONE`);
1303	  } catch (e: any) {
1304	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
1305	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
1306	    // leak the server's root password into the thrown message. Redact it before
1307	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
1308	    // sever the match. Best-effort — never let redaction lookup fail the job path.
1309	    if (job.serverId) {
1310	      try {
1311	        const s = await db.server.findUnique({
1312	          where: { id: job.serverId },
1313	          select: { rootPassword: true, rootPasswordEnc: true },
1314	        });
1315	        const pw = s ? serverRootPassword(s) : null;
1316	        if (pw) error = error.split(pw).join("***");
1317	      } catch {
1318	        /* best-effort redaction */
1319	      }
1320	    }
1321	    error = error.slice(0, 2000);
1322	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
1323	    const current = await db.job.findUnique({ where: { id: job.id } });
1324	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
1325	    await db.job.update({
1326	      where: { id: job.id },
1327	      data: { status: retriable ? "QUEUED" : "FAILED", error },
1328	    });
1329	    if (!retriable) {
1330	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1331	      // Persist terminal job failures to ErrorLog (deduped by fingerprint) so the
1332	      // admin Error Logs view surfaces what broke on the customer side, not just
1333	      // the transient Job.error. logError is already non-throwing; guard anyway.
1334	      await logError(`job.${String(job.type).toLowerCase()}`, new Error(error), {
1335	        source: "job",
1336	        jobId: job.id,
1337	        serverId: job.serverId ?? undefined,
1338	      }).catch(() => {});
1339	      if (job.serverId) {
1340	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
1341	        if (stillExists) {
1342	          // Only jobs that actually change the VM's run/disk state should strand the
1343	          // server in ERROR. Side operations — backup, snapshot-create, the control-
1344	          // panel db/website/app/cron/service ops, SSL, migrate copy, game update —
1345	          // never touch the VM's run state; their failures surface via the executor's
1346	          // own notification and must NOT flip the whole server to ERROR (a failed
1347	          // backup was wrongly making the server look like it had shut down).
1348	          if (VM_STATE_FAILURE_JOBS.has(job.type)) {
1349	            await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
1350	          }
1351	          // A terminally-failed PROVISION must not leak its allocated dedicated IP,
1352	          // nor free a NAT IP its surviving VM still holds — see cleanupFailedProvision.
1353	          if (job.type === "PROVISION") {
1354	            await cleanupFailedProvision(job.serverId);
1355	            // Tell the customer: persist the reason on the row + in-app + email.
1356	            await notifyProvisionFailed(stillExists, error).catch((err) =>
1357	              console.error(`[worker] notify provision failure ${job.id} failed`, err)
1358	            );
1359	            // Deploy-funnel: an ASYNC provisioning failure the customer never saw as
1360	            // an inline wizard error — record it so the admin funnel can attribute a
1361	            // bottom-of-funnel drop to a BUG rather than abandonment.
1362	            await recordDeployFunnelError({
1363	              product: stillExists.gamePlanId ? "game" : "vps",
1364	              step: "Provision",
1365	              stepIndex: 9,
1366	              errorCode: "PROVISION_FAILED",
1367	              errorMessage: (error.split("\n")[0] || error).slice(0, 300),
1368	              userId: stillExists.userId,
1369	            });
1370	          }
1371	        }
1372	      }
1373	    }
1374	  }
1375	}
