1377	/**
1378	 * Clean up after a terminally-failed PROVISION. Releases a dedicated IP back to
1379	 * the pool (deleting the billable OVH Virtual MAC) and clears the UNIQUE
1380	 * Server.ipAddress ONLY for a dedicated server, whose address really did return
1381	 * to the pool. A NAT server's private IP is still bound to its surviving VM's
1382	 * ipconfig0 on the bridge, so nulling Server.ipAddress would let pickFreeIp hand
1383	 * the same IP to another VM → a duplicate-IP collision (audit 2026-08-01). Both
1384	 * the runJob catch-path and reapStuckJobs call this, so neither can leak an IP.
1385	 */
1386	async function cleanupFailedProvision(serverId: string): Promise<void> {
1387	  if (SANDBOX) return;
1388	  // Capture whether it was a dedicated IP BEFORE release nulls the row's serverId.
1389	  const dedicated = await db.dedicatedIp.findUnique({ where: { serverId }, select: { id: true } });
1390	  await releaseDedicatedIp(serverId).catch((err) =>
1391	    console.error(`[worker] release dedicated IP on failed provision for ${serverId}`, err)
1392	  );
