/**
 * Per-game customization schema (MVP).
 *
 * A plain module (NO "use server") so it can be imported from server components,
 * "use server" action files AND the worker daemon alike — it holds no secrets and
 * performs no I/O.
 *
 * It declares, per game family, the available server *variants* (the loader/flavour
 * a player runs — Paper vs Vanilla, Carbon vs Oxide, …) and a versioned list of
 * *settings fields* that drive a dynamic UI. Fields are intentionally limited to
 * the handful of options players actually change, keyed on the game's own real
 * config keys (server.properties, PalWorldSettings.ini, cvars, …) — no invented
 * cvars — so a future real "apply" step can render them 1:1.
 *
 * Exports: `familyFor`, `schemaFor`, `validateConfig` plus the `GAME_CONFIG_SCHEMAS`
 * table and its types.
 */

/** Bump when the field set changes in a way the worker/apply step must notice. */
export const GAME_CONFIG_VERSION = 1;
/**
 * Resolve the game family for a server, preferring the game plan's family and
 * falling back to the OS template's family. Returns the family string ONLY if a
 * customization schema exists for it, else null.
 */
export function familyFor(server: ServerLike | null | undefined): string | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (fam && GAME_CONFIG_SCHEMAS[fam]) return fam;
  return null;
}

/** The customization schema for a family, or null. */
export function schemaFor(family: string | null | undefined): FamilySchema | null {
  if (!family) return null;
  return GAME_CONFIG_SCHEMAS[family] ?? null;
}

/** True if `variant` is a valid variant id for `family`. */
export function isValidVariant(family: string, variant: string): boolean {
  const s = GAME_CONFIG_SCHEMAS[family];
  return !!s && s.variants.some((v) => v.id === variant);
}

