// shipped without this: a VM whose IP collided with unrelated infrastructure
// (nothing was ever reachable), and separately every game family's
// `docker run -d` setup script creates no systemd unit, so the game process can
// silently fail to start while the container still shows "Up" (confirmed:
// Terraria hung on an interactive world-selection prompt with no TTY, port
// never bound) — PROVISION reported success both times. This throws on
// failure, same as every other fatal step above: the existing `runJob` catch
// path (retry while attempts remain, else ERROR + release the dedicated IP +
// `notifyProvisionFailed`) handles it, and because this runs BEFORE the
// status flip to RUNNING and the deployment email below, neither ever fires
// for a server that failed this check.
if (!SANDBOX) {
  // Same address a customer would use: the dedicated IP if one was allocated,
  // else the NAT host's public IP + this server's assigned SSH port — reusing
  // `dedicated`/`sshPort` computed earlier rather than recomputing them (see
  // the identical `sshLine` construction below).
  const sshHost = dedicated ? dedicated.address : (server.node?.publicIp ?? process.env.PUBLIC_IP);
  const sshCheckPort = dedicated ? 22 : (sshPort ?? 22);
  const ssh = await checkSshReachable(sshHost!, sshCheckPort);
  if (!ssh.ok) {
    throw new Error(
      `SSH did not respond on ${sshHost}:${sshCheckPort} after ~${Math.round(ssh.elapsedMs / 1000)}s ` +
        `(${ssh.attempts} attempt(s); last error: ${ssh.error}). The VM started, but nothing answered SSH, ` +
        `so this server cannot be handed to the customer as ready.`
    );
  }

  const game = gamePortForServer(server as unknown as ServerFamilyLike);
  if (game) {
    // `ip` is the dedicated public IP or the NAT server's private address —
    // already computed above. Only SSH gets an automatic NAT port-forward at
    // provision time; a game's own port is forwarded only if the customer adds
    // one (lib/actions-server.ts), a separate pre-existing gap this does not
    // touch. Checking against `ip` still proves what this check exists to
    // prove: the game process itself bound its port, independent of whether
    // that port has been forwarded to the internet yet.
    const gameCheck = await checkGamePortOpen(ip, game.port, game.protocol);
    if (!gameCheck.ok) {
      throw new Error(
        `game port ${game.port}/${game.protocol} never opened on ${ip} after ` +
          `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
          `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
          `server cannot be handed to the customer as ready.`
      );
    }
  } else if (server.gamePlanId) {
    // A game order whose family we could not map to a port (new game added to
    // GAME_FAMILIES/catalog without a matching lib/games.ts GAME_PORT entry).
    // This is a config gap, not evidence the server is unhealthy — log it
    // loudly for whoever ships the next game, but do not fail a customer's
    // order over our own missing map entry.
    console.error(
      `[worker] provision ${server.hostname}: game order (gamePlanId=${server.gamePlanId}, ` +
        `osTemplate.family=${server.osTemplate?.family ?? "?"}) has no GAME_PORT entry — skipped the game-port check`
    );
  }
}

const runningServer = await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });

