import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_FAMILIES } from "../lib/games.ts";
import { GAME_PORT } from "../lib/games.ts";
import {
  attemptsFor,
  retryCheck,
  gameFamilyForServer,
  gamePortForServer,
} from "../worker/provision-health.ts";

/* ------------------------------------------------------------------ *
 * GAME_PORT: every family must resolve to a real, sane port + protocol.
 * ------------------------------------------------------------------ */

test("GAME_PORT has an entry for every GAME_FAMILIES member", () => {
  for (const fam of GAME_FAMILIES) {
    assert.ok(GAME_PORT[fam], `missing GAME_PORT entry for ${fam}`);
  }
});

test("GAME_PORT entries are well-formed", () => {
  for (const [fam, entry] of Object.entries(GAME_PORT)) {
    assert.ok(Number.isInteger(entry.port), `${fam} port is not an integer`);
    assert.ok(entry.port > 0 && entry.port < 65536, `${fam} port ${entry.port} out of range`);
    assert.ok(entry.protocol === "tcp" || entry.protocol === "udp", `${fam} protocol invalid`);
  }
});

/* ------------------------------------------------------------------ *
 * attemptsFor: pure retry-count math.
 * ------------------------------------------------------------------ */

test("attemptsFor counts the first attempt plus every full interval that fits", () => {
  assert.equal(attemptsFor(0, 5_000), 1);
  assert.equal(attemptsFor(4_999, 5_000), 1);
  assert.equal(attemptsFor(5_000, 5_000), 2);
  assert.equal(attemptsFor(29_000, 5_000), 6);
  assert.equal(attemptsFor(300_000, 10_000), 31);
});

test("attemptsFor never returns fewer than 1, even for degenerate input", () => {
  assert.equal(attemptsFor(-1, 5_000), 1);
  assert.equal(attemptsFor(60_000, 0), 1);
  assert.equal(attemptsFor(60_000, -5), 1);
  assert.equal(attemptsFor(NaN, 5_000), 1);
});

/* ------------------------------------------------------------------ *
 * retryCheck: generic bounded retry loop, driven by a fake checkOnce and an
 * injected zero-delay sleep so this runs instantly regardless of the real
 * timeout/interval values passed in.
 * ------------------------------------------------------------------ */

function fakeSleep(calls: number[]) {
  return async (ms: number) => {
    calls.push(ms);
  };
}

test("retryCheck returns success immediately on the first good attempt, no sleep", async () => {
  const sleeps: number[] = [];
  let calls = 0;
  const result = await retryCheck(
    async () => {
      calls++;
      return { ok: true as const };
    },
    { timeoutMs: 60_000, intervalMs: 5_000, sleep: fakeSleep(sleeps) }
  );
  assert.equal(result.ok, true);
  assert.equal(calls, 1);
  assert.equal(sleeps.length, 0);
});

test("retryCheck retries on failure and succeeds once the check turns healthy", async () => {
  const sleeps: number[] = [];
  let calls = 0;
  const result = await retryCheck(
    async () => {
      calls++;
      if (calls < 3) return { ok: false as const, error: `not ready yet (${calls})` };
      return { ok: true as const, detail: "up" };
    },
    { timeoutMs: 60_000, intervalMs: 5_000, sleep: fakeSleep(sleeps) }
  );
  assert.equal(result.ok, true);
  assert.equal(calls, 3);
  // Slept between attempt 1->2 and 2->3, never after the final success.
  assert.deepEqual(sleeps, [5_000, 5_000]);
  assert.equal(result.ok && result.attempts, 3);
});

test("retryCheck exhausts its window and reports the LAST error, not the first", async () => {
  const sleeps: number[] = [];
  let calls = 0;
  const result = await retryCheck(
    async () => {
      calls++;
      return { ok: false as const, error: `attempt ${calls} refused` };
    },
    { timeoutMs: 20_000, intervalMs: 5_000, sleep: fakeSleep(sleeps) }
  );
  assert.equal(result.ok, false);
  const attempts = attemptsFor(20_000, 5_000);
  assert.equal(calls, attempts);
  assert.equal(result.ok === false && result.error, `attempt ${attempts} refused`);
  // Never sleeps after the final (failed) attempt either.
  assert.equal(sleeps.length, attempts - 1);
});

test("retryCheck never calls checkOnce zero times, even for a zero timeout", async () => {
  let calls = 0;
  const result = await retryCheck(
    async () => {
      calls++;
      return { ok: false as const, error: "nope" };
    },
    { timeoutMs: 0, intervalMs: 5_000, sleep: fakeSleep([]) }
  );
  assert.equal(calls, 1);
  assert.equal(result.attempts, 1);
});

/* ------------------------------------------------------------------ *
 * gameFamilyForServer / gamePortForServer: family + port resolution.
 * ------------------------------------------------------------------ */

test("gamePortForServer resolves Terraria's port from the OS template family (the incident game)", () => {
  const server = { osTemplate: { family: "terraria" } };
  assert.deepEqual(gamePortForServer(server), { port: 7777, protocol: "tcp" });
});

test("gamePortForServer prefers the game plan's family over the OS template's", () => {
  const server = { gamePlan: { gameFamily: "rust" }, osTemplate: { family: "terraria" } };
  assert.deepEqual(gamePortForServer(server), GAME_PORT.rust);
});

test("gamePortForServer falls back to the OS template family when there is no game plan", () => {
  const server = { gamePlan: null, osTemplate: { family: "valheim" } };
  assert.deepEqual(gamePortForServer(server), GAME_PORT.valheim);
});

test("gameFamilyForServer returns null for a plain VPS", () => {
  const server = { osTemplate: { family: "ubuntu" } };
  assert.equal(gameFamilyForServer(server), null);
  assert.equal(gamePortForServer(server), null);
});

test("gameFamilyForServer returns null for an unrecognized family rather than throwing", () => {
  const server = { osTemplate: { family: "some-future-game-nobody-mapped-yet" } };
  assert.equal(gameFamilyForServer(server), null);
});

test("gameFamilyForServer handles a null/undefined server", () => {
  assert.equal(gameFamilyForServer(null), null);
  assert.equal(gameFamilyForServer(undefined), null);
});

test("every GAME_FAMILIES member round-trips through gameFamilyForServer via the OS template fallback", () => {
  for (const fam of GAME_FAMILIES) {
    const server = { osTemplate: { family: fam } };
    assert.equal(gameFamilyForServer(server), fam);
    assert.deepEqual(gamePortForServer(server), GAME_PORT[fam]);
  }
});
